export { default as Sheet } from "./Sheet.vue";
export { default as SheetClose } from "./SheetClose.vue";
export { default as SheetContent } from "./SheetContent.vue";
export { default as SheetDescription } from "./SheetDescription.vue";
export { default as SheetFooter } from "./SheetFooter.vue";
export { default as SheetHeader } from "./SheetHeader.vue";
export { default as SheetTitle } from "./SheetTitle.vue";
export { default as SheetTrigger } from "./SheetTrigger.vue";
export type * from "./types.ts";

@layer components {
  /* The trigger and the close button have the look of the plain button. */
  :is([data-slot="sheet-trigger"], [data-slot="sheet-close"]) {
    align-items: center;
    background: var(--vh-bg);
    border: 1px solid var(--vh-border-accented);
    border-radius: calc(var(--vh-radius) * 0.75);
    color: var(--vh-text);
    cursor: pointer;
    display: inline-flex;
    font: inherit;
    font-size: 0.875rem;
    font-weight: 500;
    gap: 0.375rem;
    height: 2rem;
    justify-content: center;
    padding-inline: 0.75rem;
    user-select: none;
    white-space: nowrap;
  }

  @media (hover: hover) {
    :is([data-slot="sheet-trigger"], [data-slot="sheet-close"]):hover:not([data-disabled]) {
      background: var(--vh-bg-muted);
    }
  }

  :is([data-slot="sheet-trigger"], [data-slot="sheet-close"]):focus-visible {
    outline: 2px solid var(--vh-ring);
    outline-offset: 2px;
  }

  :is([data-slot="sheet-trigger"], [data-slot="sheet-close"])[data-disabled] {
    cursor: not-allowed;
    opacity: 0.5;
  }

  [data-slot="sheet-overlay"] {
    background: var(--vh-overlay);
    inset: 0;
    position: fixed;
    z-index: 50;
  }

  [data-slot="sheet-overlay"][data-hidden] {
    display: none;
  }

  /*
   * Sheet: a panel on one edge, on a shadow. ui-sdk's drawer viewport puts it on its `data-side`. The content keeps
   * ui-sdk's `drawer-content` slot, which ui-sdk needs for Escape and the Tab trap, so `data-sheet` scopes these rules.
   */
  [data-slot="drawer-content"][data-sheet] {
    background: var(--vh-bg);
    box-shadow: var(--vh-shadow-dialog);
    color: var(--vh-text);
    display: flex;
    flex-direction: column;
    font-size: 0.875rem;
    gap: 1rem;
    max-height: 85dvh;
    outline: none;
    overflow-y: auto;
    overscroll-behavior: contain;
    padding: 1.5rem;
    position: relative;
    width: 100%;
  }

  /* web.css draws a drag handle on the drawer. A sheet has none. */
  [data-slot="drawer-content"][data-sheet]::after {
    content: none;
  }

  [data-slot="drawer-content"][data-sheet]:is([data-side="left"], [data-side="right"]) {
    height: 100%;
    max-height: none;
    max-width: 85vw;
    width: 24rem;
  }

  [data-slot="drawer-content"][data-sheet][data-side="bottom"] {
    border-start-end-radius: calc(var(--vh-radius) * 1.5);
    border-start-start-radius: calc(var(--vh-radius) * 1.5);
  }

  [data-slot="drawer-content"][data-sheet][data-side="top"] {
    border-end-end-radius: calc(var(--vh-radius) * 1.5);
    border-end-start-radius: calc(var(--vh-radius) * 1.5);
  }

  /* The icon-only close button sits in the top end corner, as in shadcn. */
  [data-slot="drawer-content"][data-sheet] > [data-slot="sheet-close"][aria-label]:has(> svg:only-child) {
    background: transparent;
    border-color: transparent;
    color: var(--vh-muted);
    height: 1.75rem;
    inset-block-start: 0.75rem;
    inset-inline-end: 0.75rem;
    padding: 0;
    position: absolute;
    width: 1.75rem;
  }

  @media (hover: hover) {
    [data-slot="drawer-content"][data-sheet] > [data-slot="sheet-close"][aria-label]:has(> svg:only-child):hover {
      background: var(--vh-bg-muted);
      color: var(--vh-text);
    }
  }

  [data-slot="sheet-header"] {
    display: flex;
    flex-direction: column;
    gap: 0.375rem;
    padding-inline-end: 1.5rem;
  }

  [data-slot="sheet-title"] {
    font-size: 1rem;
    font-weight: 600;
    margin: 0;
  }

  [data-slot="sheet-description"] {
    color: var(--vh-muted);
    margin: 0;
  }

  [data-slot="sheet-footer"] {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    margin-top: auto;
  }
}

export type SheetSide = "top" | "right" | "bottom" | "left";

export interface SheetProps {
  open?: boolean;
  defaultOpen?: boolean;
  side?: SheetSide;
}

export interface SheetEmits {
  "update:open": [open: boolean];
}

export interface SheetSlots {
  default?: () => unknown;
}

export interface SheetContentProps {
  closeLabel?: string;
}

export interface SheetContentSlots {
  default?: () => unknown;
  close?: () => unknown;
}

export interface SheetTriggerSlots {
  default?: () => unknown;
}

export interface SheetCloseSlots {
  default?: () => unknown;
}

export interface SheetTitleSlots {
  default?: () => unknown;
}

export interface SheetDescriptionSlots {
  default?: () => unknown;
}

export interface SheetHeaderSlots {
  default?: () => unknown;
}

export interface SheetFooterSlots {
  default?: () => unknown;
}
